{
  "findings": [
    {
      "check_id": "CKV_AWS_135",
      "title": "Unencrypted EBS volume",
      "resource": "aws_ami.pass",
      "severity": "HIGH",
      "explanation": "The EBS block device /dev/xvda1 is not encrypted, potentially exposing sensitive data stored on the AMI."
    }
  ],
  "patched_code": "resource "aws_ami" "pass" {
  name                = "terraform-example"
  virtualization_type = "hvm"
  root_device_name    = "/dev/xvda1"

  ebs_block_device {
    device_name = "/dev/xvda1"
    volume_size = 8
    snapshot_id = "someid"
    encrypted   = true
  }

  ebs_block_device {
    device_name = "/dev/xvda2"
    volume_size = 8
    encrypted   = true
  }
}
",
  "fix_summary": "Enabled encryption on the unencrypted EBS block device /dev/xvda1."
}
